<?php
declare(strict_types=1);
if (!in_array($u['role'],['RESTAURANT_ADMIN','CASHIER'],true) || !$rid) return;
$timezone=new DateTimeZone($restaurant['timezone']??'Asia/Colombo');
$today=new DateTimeImmutable('today',$timezone);
$defaultFrom=$today->modify('-30 days')->format('Y-m-d');
$historyFrom=(string)($_GET['hist_from']??$defaultFrom);$historyTo=(string)($_GET['hist_to']??$today->format('Y-m-d'));$historyQuery=trim((string)($_GET['hist_q']??''));
$validDate=static fn(string $value):bool=>(bool)preg_match('/^\d{4}-\d{2}-\d{2}$/D',$value)&&DateTimeImmutable::createFromFormat('!Y-m-d',$value)!==false;
if(!$validDate($historyFrom))$historyFrom=$defaultFrom;if(!$validDate($historyTo))$historyTo=$today->format('Y-m-d');
$fromUtc=(new DateTimeImmutable($historyFrom.' 00:00:00',$timezone))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');
$toUtc=(new DateTimeImmutable($historyTo.' 23:59:59',$timezone))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');
$sql="SELECT ds.id,ds.session_number,ds.status,ds.started_at,ds.expires_at,ds.closed_at,t.table_number,COUNT(o.id) order_count,COALESCE(SUM(CASE WHEN o.status<>'REJECTED' THEN o.total ELSE 0 END),0) bill_total,MAX(o.updated_at) last_order_at FROM dining_sessions ds JOIN restaurant_tables t ON t.id=ds.table_id LEFT JOIN orders o ON o.dining_session_id=ds.id WHERE ds.restaurant_id=? AND ds.started_at>=? AND ds.started_at<=? AND (ds.status<>'ACTIVE' OR ds.expires_at<=UTC_TIMESTAMP())";
$params=[$rid,$fromUtc,$toUtc];
if($historyQuery!==''){$sql.=" AND (t.table_number LIKE ? OR ds.session_number LIKE ? OR EXISTS(SELECT 1 FROM orders oq WHERE oq.dining_session_id=ds.id AND oq.order_number LIKE ?))";$like='%'.$historyQuery.'%';array_push($params,$like,$like,$like);}
$sql.=' GROUP BY ds.id,t.table_number HAVING COUNT(o.id)>0 ORDER BY ds.started_at DESC LIMIT 300';$statement=$db->prepare($sql);$statement->execute($params);$historyRows=$statement->fetchAll();
$recentHistory=[];$olderHistory=[];
foreach($historyRows as $record){$localStart=(new DateTimeImmutable($record['started_at'],new DateTimeZone('UTC')))->setTimezone($timezone);$record['local_start']=$localStart;$record['local_expiry']=(new DateTimeImmutable($record['expires_at'],new DateTimeZone('UTC')))->setTimezone($timezone);if($localStart->format('Y-m-d')===$today->format('Y-m-d'))$recentHistory[]=$record;else $olderHistory[]=$record;}
$renderHistory=static function(array $rows)use($e):string{if(!$rows)return '<p class="history-empty">No table sessions found for this period.</p>';$out='<div class="table-history-list">';foreach($rows as $row){$out.='<article class="table-history-card"><div class="table-history-table"><span>TABLE</span><strong>'.$e($row['table_number']).'</strong></div><div class="table-history-copy"><small>BILL SESSION</small><strong>'.$e($row['session_number']).'</strong><span>'.$e($row['local_start']->format('M d, Y · h:i A')).' – '.$e($row['local_expiry']->format('h:i A')).'</span></div><div class="table-history-stat"><small>Orders</small><strong>'.(int)$row['order_count'].'</strong></div><div class="table-history-stat"><small>Bill total</small><strong>LKR '.number_format((float)$row['bill_total'],2).'</strong></div><span class="table-history-status">'.$e($row['status']).'</span></article>';}$out.='</div>';return $out;};
$history='<section class="panel" id="table-history"><div class="history-title"><div><p class="eyebrow">ARCHIVE</p><h2>Table History</h2><p>Sessions automatically move here after six hours. Search bills, tables or order numbers.</p></div><span>'.count($historyRows).' records</span></div><form method="get" action="'.$e($base).'/dashboard#table-history" class="table-history-filters"><label>Search<input type="search" name="hist_q" value="'.$e($historyQuery).'" placeholder="Table, bill or order number"></label><label>From date<input type="date" name="hist_from" value="'.$e($historyFrom).'"></label><label>To date<input type="date" name="hist_to" value="'.$e($historyTo).'"></label><button>View History</button><a class="button" href="'.$e($base).'/dashboard#table-history">Reset</a></form><div class="history-group"><h3>Today · Older than 6 hours</h3>'.$renderHistory($recentHistory).'</div><div class="history-group"><h3>Previous days</h3>'.$renderHistory($olderHistory).'</div></section>';
$html=str_replace('</main>',$history.'</main>',$html);
